<?php declare(strict_types=1);require_once dirname(__DIR__,2).'/security.php';$pages=max(1,(int)ceil($total/$perPage));$h=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Program Specifications</title><link rel="stylesheet" href="/assets/style.css"><style>main{max-width:1200px;margin:auto;padding:1rem}.filters,.actions,.pagination{display:flex;gap:.6rem;flex-wrap:wrap;align-items:end}.field label{display:block;font-weight:700}.table-scroll{overflow-x:auto;margin-top:1rem}table{width:100%;border-collapse:collapse}th,td{padding:.65rem;border:1px solid #ccc;text-align:left}.status{padding:.6rem;background:#eef}@media(max-width:700px){th:nth-child(4),td:nth-child(4){display:none}}</style></head><body><?php require dirname(__DIR__,2).'/nav.php';?><main id="main-content"><h1>Program Specifications</h1><p class="status" role="status"><?= (int)$total ?> accessible specification(s)</p><form class="filters" method="get" action="/program-specifications" role="search"><div class="field"><label for="program-search">Search</label><input id="program-search" name="search" maxlength="100" value="<?=$h($filters['search'])?>"></div><div class="field"><label for="approval-status">Approval status</label><select id="approval-status" name="approval_status"><option value="">All</option><?php foreach(['Draft','Under Review','Approved','Archived'] as $value):?><option <?=$filters['approval_status']===$value?'selected':''?>><?=$h($value)?></option><?php endforeach;?></select></div><div class="field"><label for="specification-type">Type</label><select id="specification-type" name="specification_type"><option value="">All</option><?php foreach(['New','Updated'] as $value):?><option <?=$filters['specification_type']===$value?'selected':''?>><?=$h($value)?></option><?php endforeach;?></select></div><button type="submit">Filter</button></form><?php if(\QualitySystem\Security\PermissionMatrix::allows($role,'programs','create')):?><p><a class="btn" href="/program-specifications/create">Add program specification</a></p><?php endif;?><div class="table-scroll" tabindex="0" aria-label="Program specification results"><table><caption>Program specifications you are authorized to access</caption><thead><tr><th scope="col">Specification</th><th scope="col">Status</th><th scope="col">Type</th><th scope="col">Study plan</th><th scope="col">Content</th><th scope="col">Actions</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong><?=$h($row['specification_title'])?></strong><br><?=$h($row['program_name'])?> <?=$h($row['program_code'])?></td><td><?=$h($row['approval_status']??'Draft')?></td><td><?=$h($row['specification_type']??'')?></td><td><?=$h($row['study_plan_title']??'Not linked')?></td><td><?= (int)$row['plo_count']?> PLOs; <?= (int)$row['course_count']?> courses; <?= (int)$row['kpi_count']?> KPIs</td><td><div class="actions"><a href="/program_specification_profile.php?id=<?=(int)$row['id']?>">View</a><a href="/program_specification_dashboard.php?id=<?=(int)$row['id']?>">Dashboard</a><a href="/program_specification_readiness.php?id=<?=(int)$row['id']?>">Readiness</a><a href="/program_specification_exports.php?id=<?=(int)$row['id']?>">Exports</a><a href="/program_specification_validation.php?id=<?=(int)$row['id']?>">Validation</a><?php if(\QualitySystem\Security\PermissionMatrix::allows($role,'programs','update')):?><a href="/program-specifications/<?=(int)$row['id']?>/edit">Edit</a><?php endif;?><?php if(\QualitySystem\Security\PermissionMatrix::allows($role,'programs','delete')):?><form method="post" action="/program-specifications/<?=(int)$row['id']?>/delete" onsubmit="return confirm('Delete this empty program specification?')"><?=csrfField()?><button type="submit">Delete</button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">No accessible program specifications found.</td></tr><?php endif;?></tbody></table></div><nav class="pagination" aria-label="Program specification result pages"><?php for($n=1;$n<=$pages&&$n<=100;$n++):?><a <?=$n===$page?'aria-current="page"':''?> href="/program-specifications?<?=http_build_query($filters+['page'=>$n,'per_page'=>$perPage])?>"><?=$n?></a><?php endfor;?></nav></main></body></html>
